import unittest
from candidate import fib4

class TestFib4(unittest.TestCase):
    def test_fib4_zero(self):
        self.assertEqual(fib4(0), 0)

    def test_fib4_one(self):
        self.assertEqual(fib4(1), 0)

    def test_fib4_two(self):
        self.assertEqual(fib4(2), 2)

    def test_fib4_three(self):
        self.assertEqual(fib4(3), 0)

    def test_fib4_four(self):
        self.assertEqual(fib4(4), 4)

    def test_fib4_five(self):
        self.assertEqual(fib4(5), 4)

    def test_fib4_six(self):
        self.assertEqual(fib4(6), 8)

    def test_fib4_seven(self):
        self.assertEqual(fib4(7), 14)

    def test_fib4_eight(self):
        self.assertEqual(fib4(8), 20)

    def test_fib4_nine(self):
        self.assertEqual(fib4(9), 34)

    def test_fib4_ten(self):
        self.assertEqual(fib4(10), 54)

    def test_fib4_large_input(self):
        self.assertEqual(fib4(20), 35890)

    def test_fib4_negative_input(self):
        with self.assertRaises(ValueError):
            fib4(-1)

    def test_fib4_non_integer_input(self):
        with self.assertRaises(TypeError):
            fib4(1.5)

    def test_fib4_none_input(self):
        with self.assertRaises(TypeError):
            fib4(None)
